public Mappings diffStructure(String tableName, Mappings mappings) {
    // Get the mapping for the given table
    Mapping tableMapping = mappings.get(tableName);

    // Check if the table mapping exists in the input mappings
    if (tableMapping == null) {
        throw new IllegalArgumentException("Table " + tableName + " does not exist in the input mappings");
    }

    // Get the mapping from the current index
    Mapping currentMapping = new MappingBuilder().buildFrom(tableMapping.getSource().get(0));

    // Get the mapping from the input mappings
    Mapping inputMapping = new MappingBuilder().buildFrom(mappings.get(tableName));

    // Diff the fields and create a new mapping for the field differences
    Mapping diffMapping = currentMapping.diffWith(inputMapping, Mapping::fieldExists);

    // Remove the _source config from the diff mapping
    diffMapping.getSource().removeIf(field -> field.getName().equals("_source"));

    return diffMapping;
}
