private String parseToken(char[] terminators) {
    int currentPosition = 0;
    StringBuilder token = new StringBuilder();
    while (currentPosition < terminators.length) {
        char c = terminators[currentPosition];
        if (isParenthesis(c)) {
            if (c == '(') {
                int depth = 1;
                while (depth > 0) {
                    currentPosition++;
                    c = terminators[currentPosition];
                    if (c == '(') {
                        depth++;
                    } else if (c == ')') {
                        depth--;
                    }
                }
            } else if (c == '[') {
                int depth = 1;
                while (depth > 0) {
                    currentPosition++;
                    c = terminators[currentPosition];
                    if (c == '[') {
                        depth++;
                    } else if (c == ']') {
                        depth--;
                    }
                }
            } else {
                currentPosition++;
            }
        } else if (isConcurrencyTokenSeparator(c)) {
            currentPosition++;
        } else {
            token.append(c);
            currentPosition++;
        }
    }
    return token.toString();
}

